/**
 * Something that can be done on an area (gardening, beekeeping…), known by its code. Every
 * field is optional: an endpoint says which ones it gives, a component which ones it needs
 * (`WithRequired`).
 */
export interface AreaActivity {
  id?: string;
  code?: string;
  createdAt?: Date;
}

/** What the creation form gives. */
export interface AreaActivityCreateInput {
  /** Generated by the API when left out. */
  id?: AreaActivity['id'];
  code: NonNullable<AreaActivity['code']>;
}

/** The fields to change; those left out are kept. */
export type AreaActivityUpdateInput = Partial<Omit<AreaActivityCreateInput, 'id'>>;
